# CG_Setup_AllInOne_v3.ps1
# One-file installer for legacy WinBGIm/graphics.h + MSYS2 MINGW64 + VS Code.
# Requires Administrator privileges.
$ErrorActionPreference = "Stop"

$MSYS2_ROOT = "C:\msys64"
$MINGW_BIN = Join-Path $MSYS2_ROOT "mingw64\bin"
$MINGW_INCLUDE = Join-Path $MSYS2_ROOT "mingw64\include"
$MINGW_LIB = Join-Path $MSYS2_ROOT "mingw64\lib"
$BASH = Join-Path $MSYS2_ROOT "usr\bin\bash.exe"
$GXX = Join-Path $MINGW_BIN "g++.exe"
$PACMAN = Join-Path $MSYS2_ROOT "usr\bin\pacman.exe"

function Write-Ok($m)   { Write-Host "[OK] $m" -ForegroundColor Green }
function Write-Info($m) { Write-Host "[INFO] $m" -ForegroundColor Cyan }
function Write-Warn($m) { Write-Host "[WARN] $m" -ForegroundColor Yellow }
function Fail($m) { throw $m }

# ----- Administrator check -----
$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Fail "Please run PowerShell as Administrator."
}

# ----- Embedded WinBGIm assets -----
$B64_GRAPHICS = @'

'@
$B64_WINBGIM = @'

'@
$B64_LIBBGI = @'

'@

function Write-EmbeddedFile([string]$Base64, [string]$Path) {
    $dir = Split-Path -Parent $Path
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String(($Base64 -replace '\s','')))
}

function Sha256([string]$Path) {
    return (Get-FileHash -Algorithm SHA256 -Path $Path).Hash.ToLower()
}

# ----- JSONC parser helpers -----
# VS Code accepts JSON with comments/trailing commas. Windows PowerShell's
# ConvertFrom-Json does not. These functions remove comments/commas while
# respecting quoted strings.
function Strip-JsonComments([string]$Text) {
    $sb = New-Object Text.StringBuilder
    $inString = $false
    $escape = $false
    $lineComment = $false
    $blockComment = $false
    for ($i=0; $i -lt $Text.Length; $i++) {
        $c = $Text[$i]
        $n = if ($i+1 -lt $Text.Length) { $Text[$i+1] } else { [char]0 }

        if ($lineComment) {
            if ($c -eq "`r" -or $c -eq "`n") {
                $lineComment = $false
                [void]$sb.Append($c)
            }
            continue
        }

        if ($blockComment) {
            if ($c -eq '*' -and $n -eq '/') {
                $blockComment = $false
                $i++
            } elseif ($c -eq "`r" -or $c -eq "`n") {
                [void]$sb.Append($c)
            }
            continue
        }

        if ($inString) {
            [void]$sb.Append($c)
            if ($escape) { $escape = $false }
            elseif ($c -eq '\') { $escape = $true }
            elseif ($c -eq '"') { $inString = $false }
            continue
        }

        if ($c -eq '"') {
            $inString = $true
            [void]$sb.Append($c)
        } elseif ($c -eq '/' -and $n -eq '/') {
            $lineComment = $true
            $i++
        } elseif ($c -eq '/' -and $n -eq '*') {
            $blockComment = $true
            $i++
        } else {
            [void]$sb.Append($c)
        }
    }
    return $sb.ToString()
}

function Strip-TrailingCommas([string]$Text) {
    $sb = New-Object Text.StringBuilder
    $inString = $false
    $escape = $false
    for ($i=0; $i -lt $Text.Length; $i++) {
        $c = $Text[$i]
        if ($inString) {
            [void]$sb.Append($c)
            if ($escape) { $escape = $false }
            elseif ($c -eq '\') { $escape = $true }
            elseif ($c -eq '"') { $inString = $false }
            continue
        }

        if ($c -eq '"') {
            $inString = $true
            [void]$sb.Append($c)
            continue
        }

        if ($c -eq ',') {
            $j = $i + 1
            while ($j -lt $Text.Length -and [char]::IsWhiteSpace($Text[$j])) { $j++ }
            if ($j -lt $Text.Length -and ($Text[$j] -eq '}' -or $Text[$j] -eq ']')) {
                continue
            }
        }
        [void]$sb.Append($c)
    }
    return $sb.ToString()
}

function Read-Jsonc([string]$Path) {
    $raw = [IO.File]::ReadAllText($Path)
    $clean = Strip-TrailingCommas (Strip-JsonComments $raw)
    return ($clean | ConvertFrom-Json)
}

function Backup-File([string]$Path) {
    if (Test-Path $Path) {
        $stamp = Get-Date -Format "yyyyMMdd-HHmmss"
        $backup = "$Path.cg-backup-$stamp"
        Copy-Item $Path $backup -Force
        Write-Info "Backup: $backup"
        return $backup
    }
    return $null
}

function Save-Json([object]$Object, [string]$Path) {
    $json = $Object | ConvertTo-Json -Depth 30
    [IO.File]::WriteAllText($Path, $json, (New-Object Text.UTF8Encoding($false)))
}

function Ensure-Property([object]$Object, [string]$Name, [object]$Value) {
    $p = $Object.PSObject.Properties[$Name]
    if ($null -ne $p) {
        $Object.PSObject.Properties.Remove($Name)
    }
    $Object | Add-Member -NotePropertyName $Name -NotePropertyValue $Value
}

# ----- MSYS2 -----
Write-Host ""
Write-Host "=== Checking MSYS2 ===" -ForegroundColor White

if (-not (Test-Path $MSYS2_ROOT)) {
    Write-Info "MSYS2 not found. Downloading the current official installer..."
    $tmp = Join-Path $env:TEMP "msys2-x86_64-latest.exe"
    Invoke-WebRequest -Uri "https://github.com/msys2/msys2-installer/releases/latest/download/msys2-x86_64-latest.exe" -OutFile $tmp
    Write-Info "Installing MSYS2 to C:\msys64..."
    $p = Start-Process -FilePath $tmp -ArgumentList "in","--confirm-command","--accept-messages","--root","C:/msys64" -Wait -PassThru
    if ($p.ExitCode -ne 0 -or -not (Test-Path $BASH)) {
        Fail "MSYS2 installation failed. Exit code: $($p.ExitCode)"
    }
    Remove-Item $tmp -Force -ErrorAction SilentlyContinue
}
Write-Ok "MSYS2 found at $MSYS2_ROOT"

# ----- GCC -----
Write-Host ""
Write-Host "=== Checking MINGW64 GCC ===" -ForegroundColor White

if (-not (Test-Path $GXX)) {
    Write-Info "MINGW64 GCC not found. Updating package database..."
    & $BASH -lc "pacman -Sy --noconfirm" | Out-Host
    if ($LASTEXITCODE -ne 0) {
        Write-Warn "Package database refresh returned exit code $LASTEXITCODE; continuing to GCC install."
    }

    Write-Info "Installing mingw-w64-x86_64-gcc..."
    & $BASH -lc "pacman -S --needed --noconfirm mingw-w64-x86_64-gcc" | Out-Host
    if ($LASTEXITCODE -ne 0 -or -not (Test-Path $GXX)) {
        Fail "Could not install MINGW64 GCC."
    }
}
Write-Ok "MINGW64 g++ found: $GXX"

# ----- WinBGIm -----
Write-Host ""
Write-Host "=== Installing WinBGIm ===" -ForegroundColor White

Write-EmbeddedFile $B64_GRAPHICS (Join-Path $MINGW_INCLUDE "graphics.h")
Write-EmbeddedFile $B64_WINBGIM  (Join-Path $MINGW_INCLUDE "winbgim.h")
Write-EmbeddedFile $B64_LIBBGI   (Join-Path $MINGW_LIB "libbgi64.a")

$h1 = Sha256 (Join-Path $MINGW_INCLUDE "graphics.h")
$h2 = Sha256 (Join-Path $MINGW_INCLUDE "winbgim.h")
$h3 = Sha256 (Join-Path $MINGW_LIB "libbgi64.a")

if ($h1 -ne "61122e90493c2cb9f55c6a96c5c44698eb51486907b4ac2614875da1c16577e6") { Fail "graphics.h verification failed." }
if ($h2 -ne "61122e90493c2cb9f55c6a96c5c44698eb51486907b4ac2614875da1c16577e6") { Fail "winbgim.h verification failed." }
if ($h3 -ne "db74ca3eeacd7498f447a83a0a72e4f4e2b813bc042d23ee16b874bb47195420") { Fail "libbgi64.a verification failed." }
Write-Ok "WinBGIm files installed and verified."

# ----- VS Code -----
Write-Host ""
Write-Host "=== Configuring VS Code ===" -ForegroundColor White

$codeUser = Join-Path $env:APPDATA "Code\User"
if (-not (Test-Path $codeUser)) { New-Item -ItemType Directory -Path $codeUser -Force | Out-Null }

# IMPORTANT: Do not parse/rewrite VS Code JSONC. VS Code configuration files may
# contain comments and other JSONC constructs that Windows PowerShell cannot parse.
# We edit only the exact sections we need, preserving the user's original text.
function Backup-Once([string]$Path) {
    if (-not (Test-Path $Path)) { return $null }
    $stamp = Get-Date -Format "yyyyMMdd-HHmmss"
    $backup = "$Path.cg-backup-$stamp"
    Copy-Item $Path $backup -Force
    Write-Info "Backup: $backup"
    return $backup
}

function Find-MatchingBrace([string]$Text, [int]$OpenIndex) {
    $depth = 0
    $inString = $false
    $escape = $false
    $lineComment = $false
    $blockComment = $false
    for ($i=$OpenIndex; $i -lt $Text.Length; $i++) {
        $c = $Text[$i]
        $n = if ($i+1 -lt $Text.Length) { $Text[$i+1] } else { [char]0 }
        if ($lineComment) {
            if ($c -eq "`r" -or $c -eq "`n") { $lineComment = $false }
            continue
        }
        if ($blockComment) {
            if ($c -eq '*' -and $n -eq '/') { $blockComment=$false; $i++ }
            continue
        }
        if ($inString) {
            if ($escape) { $escape=$false }
            elseif ($c -eq '\') { $escape=$true }
            elseif ($c -eq '"') { $inString=$false }
            continue
        }
        if ($c -eq '"') { $inString=$true; continue }
        if ($c -eq '/' -and $n -eq '/') { $lineComment=$true; $i++; continue }
        if ($c -eq '/' -and $n -eq '*') { $blockComment=$true; $i++; continue }
        if ($c -eq '{') { $depth++ }
        elseif ($c -eq '}') {
            $depth--
            if ($depth -eq 0) { return $i }
        }
    }
    return -1
}

function Insert-Text([string]$Text, [int]$Index, [string]$Insertion) {
    return $Text.Substring(0,$Index) + $Insertion + $Text.Substring($Index)
}

# --- settings.json: add a uniquely named CG terminal profile without parsing JSONC ---
$settingsPath = Join-Path $codeUser "settings.json"
if (-not (Test-Path $settingsPath)) {
    $settingsText = "{`r`n}"
    [IO.File]::WriteAllText($settingsPath, $settingsText, (New-Object Text.UTF8Encoding($false)))
} else {
    Backup-Once $settingsPath
    $settingsText = [IO.File]::ReadAllText($settingsPath)
}

$profileName = 'CG MSYS2 MINGW64'
$profileEntry = "`r`n        `"$profileName`": {`r`n            `"path`": `"C:\\msys64\\usr\\bin\\bash.exe`",`r`n            `"args`": [`"--login`", `"-i`"],`r`n            `"env`": {`r`n                `"MSYSTEM`": `"MINGW64`",`r`n                `"CHERE_INVOKING`": `"1`"`r`n            }`r`n        },"

if ($settingsText -notmatch [regex]::Escape($profileName)) {
    $profilesMatch = [regex]::Match($settingsText, '"terminal\.integrated\.profiles\.windows"\s*:\s*\{')
    if ($profilesMatch.Success) {
        $open = $settingsText.IndexOf('{', $profilesMatch.Index)
        $close = Find-MatchingBrace $settingsText $open
        if ($close -lt 0) { Fail "Could not safely locate terminal profile section in VS Code settings.json. Backup was created; no settings were overwritten." }
        $settingsText = Insert-Text $settingsText ($open+1) $profileEntry
    } else {
        # Insert a new top-level property before the final object brace.
        $last = $settingsText.LastIndexOf('}')
        if ($last -lt 0) { Fail "Could not safely locate the end of VS Code settings.json. Backup was created; no settings were overwritten." }
        $prefix = $settingsText.Substring(0,$last).TrimEnd()
        $needsComma = ($prefix -notmatch '\{\s*$')
        $addition = "`r`n    `"terminal.integrated.profiles.windows`": {`r`n        `"$profileName`": {`r`n            `"path`": `"C:\\msys64\\usr\\bin\\bash.exe`",`r`n            `"args`": [`"--login`", `"-i`"],`r`n            `"env`": { `"MSYSTEM`": `"MINGW64`", `"CHERE_INVOKING`": `"1`" }`r`n        }`r`n    }`r`n"
        if ($needsComma) { $addition = "," + $addition }
        $settingsText = $prefix + $addition + $settingsText.Substring($last)
    }
    [IO.File]::WriteAllText($settingsPath, $settingsText, (New-Object Text.UTF8Encoding($false)))
}
Write-Ok "VS Code MINGW64 terminal profile configured."

# --- tasks.json: inject one user task into the existing tasks array without parsing JSONC ---
$tasksPath = Join-Path $codeUser "tasks.json"
$cgTaskText = @'
{
    "label": "CG: Build Current File",
    "type": "process",
    "command": "C:\\msys64\\mingw64\\bin\\g++.exe",
    "args": [
        "${file}",
        "-o",
        "${fileDirname}\\${fileBasenameNoExtension}.exe",
        "C:\\msys64\\mingw64\\lib\\libbgi64.a",
        "-lgdi32",
        "-lcomdlg32",
        "-luuid",
        "-loleaut32",
        "-lole32",
        "-Wno-write-strings"
    ],
    "group": { "kind": "build", "isDefault": false },
    "problemMatcher": "$gcc"
}
'@

if (-not (Test-Path $tasksPath)) {
    $tasksText = "{`r`n    `"version`": `"2.0.0`",`r`n    `"tasks`": [`r`n" + $cgTaskText + "`r`n    ]`r`n}`r`n"
    [IO.File]::WriteAllText($tasksPath, $tasksText, (New-Object Text.UTF8Encoding($false)))
} else {
    Backup-Once $tasksPath
    $tasksText = [IO.File]::ReadAllText($tasksPath)
    if ($tasksText -notmatch [regex]::Escape('CG: Build Current File')) {
        $tm = [regex]::Match($tasksText, '"tasks"\s*:\s*\[')
        if (-not $tm.Success) { Fail "Could not safely locate the tasks array in VS Code tasks.json. Backup was created; no tasks were overwritten." }
        $arrayOpen = $tasksText.IndexOf('[', $tm.Index)
        $insert = "`r`n" + $cgTaskText.TrimEnd() + ","
        $tasksText = Insert-Text $tasksText ($arrayOpen+1) $insert
        [IO.File]::WriteAllText($tasksPath, $tasksText, (New-Object Text.UTF8Encoding($false)))
    }
}
Write-Ok "Global CG build task configured."

# ----- Verification -----
Write-Host ""
Write-Host "=== Verification ===" -ForegroundColor White

$testDir = Join-Path $env:TEMP "CG_Setup_Verify"
if (Test-Path $testDir) { Remove-Item $testDir -Recurse -Force }
New-Item -ItemType Directory -Path $testDir -Force | Out-Null
$testCpp = Join-Path $testDir "cg_verify.cpp"
$testExe = Join-Path $testDir "cg_verify.exe"

@'
#include <graphics.h>
int main() {
    initwindow(320, 240, "CG Setup Verification");
    circle(160, 120, 50);
    closegraph();
    return 0;
}
'@ | Set-Content -Path $testCpp -Encoding ASCII

Write-Info "Compiling graphics.h smoke test..."
& $GXX $testCpp -o $testExe (Join-Path $MINGW_LIB "libbgi64.a") -lgdi32 -lcomdlg32 -luuid -loleaut32 -lole32 -Wno-write-strings
if ($LASTEXITCODE -ne 0 -or -not (Test-Path $testExe)) {
    Remove-Item $testDir -Recurse -Force -ErrorAction SilentlyContinue
    Fail "graphics.h compilation test FAILED."
}
Remove-Item $testDir -Recurse -Force -ErrorAction SilentlyContinue
Write-Ok "graphics.h + WinBGIm compilation test passed."

Write-Host ""
Write-Host "==========================================" -ForegroundColor Green
Write-Host "          CG SETUP COMPLETE" -ForegroundColor Green
Write-Host "==========================================" -ForegroundColor Green
Write-Host ""
Write-Host "VS Code workflow:" -ForegroundColor White
Write-Host "  1. Open any CG folder"
Write-Host "  2. Open your .cpp file"
Write-Host "  3. Terminal -> Run Task -> CG: Build Current File"
Write-Host "  4. Run the generated .exe from the MINGW64 terminal"
Write-Host ""
Write-Host "No Windows PATH changes were made." -ForegroundColor Cyan
Write-Host ""
